import{createCoreEastForeground}from'./core-east-foreground.mjs';
import{loadCurrentLighting}from'./lighting-loader.mjs';
import{loadPrologueVisualLayer}from'../prologue-native/visual-layer.mjs';
import{loadApprovedPlayers,drawApprovedPlayer}from'../../art/approved-player-field.mjs';
import{HUB_REGISTRATION as H}from'./hub-support.mjs';
const moduleURL=import.meta.url;const imageURL=new URL('../prologue-native/assets/prologue.png',moduleURL);
const hash=async b=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',b))].map(v=>v.toString(16).padStart(2,'0')).join('');
// Selected visual provider only: no P0 movement, ports, authority, world, timer or save ownership.
// Original water/boat receiver and selected three overlays are shared as immutable visual inputs.
export async function loadS9HubView({fetcher=fetch,decode=b=>createImageBitmap(new Blob([b],{type:'image/png'})),signal,canvasFactory}={}){
 let image=null,visual=null,lighting=null,coreEast=null,actorMask=null,disposed=false;const closeErrors=[],closed=new WeakSet();const ownedDecode=async bytes=>{const bitmap=await decode(bytes),close=bitmap.close?.bind(bitmap);if(close)Object.defineProperty(bitmap,'close',{configurable:true,value(){if(closed.has(bitmap))return;closed.add(bitmap);try{close()}catch(e){closeErrors.push(String(e.message??e))}}});return bitmap};const check=()=>{if(disposed||signal?.aborted)throw Error('S9_HUB_VIEW_CANCELLED')};const dispose=()=>{if(disposed)return;disposed=true;try{visual?.dispose()}finally{try{if(actorMask){actorMask.width=0;actorMask.height=0;actorMask=null}}finally{try{lighting?.dispose()}finally{try{coreEast?.dispose()}finally{image?.close?.()}}}}};
 try{check();const response=await fetcher(imageURL,{signal});if(!response.ok)throw Error('S9_HUB_ART_HTTP');const raw=await response.arrayBuffer(),bytes=raw instanceof ArrayBuffer?new Uint8Array(raw.slice(0)):new Uint8Array(raw);check();if(await hash(bytes)!==H.imageSHA)throw Error('S9_HUB_ART_PIN');check();image=await ownedDecode(bytes);check();if(image.width!==H.width||image.height!==H.height)throw Error('S9_HUB_ART_DIMENSIONS');visual=await loadPrologueVisualLayer({fetcher,decode:ownedDecode,signal,canvasFactory});check();await loadApprovedPlayers();check();lighting=await loadCurrentLighting({fetcher,signal});check();coreEast=createCoreEastForeground({image,canvasFactory:canvasFactory??((w,h)=>{const c=document.createElement('canvas');c.width=w;c.height=h;return c})});check();
 return Object.freeze({revision:H.revision,teardownDiagnostics:()=>[...closeErrors],draw(ctx,location,{elapsedMs=0,moving=false,walk=0,appearance='boy',minutes}={}){check();if(!Number.isFinite(minutes))throw Error('S9_MAIN_CLOCK_REQUIRED');if(location?.sceneId!==H.sceneId||location.mapId!==H.mapId||location.revision!==H.revision||!Array.isArray(location.foot)||!location.foot.every(Number.isSafeInteger))throw Error('S9_HUB_VIEW_POSE');const[x,y]=location.foot,w=ctx.canvas.width,h=ctx.canvas.height,cx=Math.max(0,Math.min(H.width-w,x-w/2)),cy=Math.max(0,Math.min(H.height-h,y-h/2));actorMask??=(canvasFactory??((w,h)=>{const c=document.createElement('canvas');c.width=w;c.height=h;return c}))(w,h);ctx.save();try{ctx.imageSmoothingEnabled=false;ctx.clearRect(0,0,w,h);ctx.drawImage(image,cx,cy,w,h,0,0,w,h);visual.draw(ctx,{offsetX:cx,offsetY:cy,elapsedMs});const actor=drawApprovedPlayer(ctx,{x:x-cx,y:y-cy,facing:location.facing,moving,walk,visibleHeight:80,appearance});if(!actor)throw Error('S9_APPROVED_PLAYER_NOT_READY');visual.drawForeground(ctx,{offsetX:cx,offsetY:cy,actorFoot:[x,y]});coreEast.draw(ctx,{offsetX:cx,offsetY:cy,actorFoot:[x,y]});const current=ctx.getImageData(0,0,w,h),visibleActor=captureVisibleActorAlpha(actorMask,maskCtx=>drawApprovedPlayer(maskCtx,{x:x-cx,y:y-cy,facing:location.facing,moving,walk,visibleHeight:80,appearance}),maskCtx=>{visual.drawForeground(maskCtx,{offsetX:cx,offsetY:cy,actorFoot:[x,y]});coreEast.draw(maskCtx,{offsetX:cx,offsetY:cy,actorFoot:[x,y]})});const output=new Uint8ClampedArray(current.data.length),stats=lighting.draw(current.data,output,{minutes,camera:[cx,cy],actorAlpha:visibleActor});if(stats.nightMix>0){current.data.set(output);ctx.putImageData(current,0,0)}return{camera:[cx,cy],actor,lighting:stats};}finally{ctx.restore()}},dispose});
 }catch(e){dispose();throw e}
}

export function captureVisibleActorAlpha(mask,drawActor,drawForeground){const c=mask.getContext('2d');c.save();try{c.globalCompositeOperation='source-over';c.clearRect(0,0,mask.width,mask.height);drawActor(c);c.globalCompositeOperation='destination-out';drawForeground(c)}finally{c.restore()}const pixels=c.getImageData(0,0,mask.width,mask.height).data,alpha=new Uint8Array(mask.width*mask.height);for(let i=0;i<alpha.length;i++)alpha[i]=pixels[i*4+3];return alpha}
